sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {

    var elementId = event.elementId;

    var sysId = event.context.item.value._row_data.uniqueValue;

    var value = event.payload.value;
    c// onsole.log(elementId + " :: " + sysId);


    let updatedData = JSON.parse(JSON.stringify(api.state.updatedData));


    let element = updatedData[sysId] || {};
    element[elementId] = value;
    updatedData[sysId] = element;
    api.setState('updatedData', updatedData);
    console.log(updatedData);

}
